set res(_res: Response | undefined) {
  // Headers staged by `c.header()` live in `#preparedHeaders` until something
  // reads `c.res`. Fall back to them so they are not dropped when a raw
  // Response is assigned before `c.res` has been materialized.
  const existingHeaders = this.#res ? this.#res.headers : this.#preparedHeaders
  if (existingHeaders && _res) {
    _res = createResponseInstance(_res.body, _res)
    // Capture cookies from both responses before modifying the new response.
    // `Set-Cookie` is the only header that can legitimately appear more than
    // once, so it is merged after the loop instead of being overwritten.
    const existingCookies = existingHeaders.getSetCookie()
    const incomingCookies = _res.headers.getSetCookie()

    for (const [k, v] of existingHeaders.entries()) {
      if (k === 'content-type' || k === 'set-cookie') {
        continue
      }
      _res.headers.set(k, v)
    }

    if (existingCookies.length > 0) {
      const cookies = [...existingCookies]
      const existingSet = new Set(existingCookies)
      for (const cookie of incomingCookies) {
        // A response built from the context's own headers (for example via
        // `c.text()`) already carries these cookies, so don't duplicate them.
        if (!existingSet.has(cookie)) {
          cookies.push(cookie)
        }
      }
      _res.headers.delete('set-cookie')
      for (const cookie of cookies) {
        _res.headers.append('set-cookie', cookie)
      }
    }
  }
  if (!_res) {
    // `c.res = undefined` resets the response, so discard staged headers too.
    this.#preparedHeaders = undefined
  }
  this.#res = _res
  this.finalized = true
}

